import java.util.Arrays;
import java.util.List;

public class ArraysUtilityDemo {
    public static void main(String[] args) {
        int[] data = {42, 15, 8, 99, 23, 4, 15};

        // 1. Sorting primitives
        Arrays.sort(data);
        System.out.println("Sorted: " + Arrays.toString(data));

        // 2. Binary search (array must be sorted first)
        int index = Arrays.binarySearch(data, 23);
        System.out.println("Element 23 found at index: " + index);

        // 3. Creating a fixed-size list view from an array
        String[] names = {"Alice", "Bob", "Charlie"};
        List<String> nameList = Arrays.asList(names);

        // Mutations affect the underlying array
        nameList.set(0, "Alicia");
        System.out.println("Modified array element: " + names[0]);
    }
}
